#!/bin/sh
# One-off helper, not run by CI: extracts a real saved project for each released
# project-format version into crates/model/tests/fixtures/demo-vN.atomik.
#
# The demo project in examples/projects/demo.atomik is the canonical save of the demo
# (a test keeps it so) and is regenerated by every commit that bumps PROJECT_VERSION, so
# the copy at the bump commit is a file written by that version's own writer.
#
# usage: sh scripts/extract-format-fixtures.sh [FIRST [LAST]]     (defaults 13 and the current version)
set -eu
cd "$(dirname "$0")/.."
src=crates/model/src/project.rs
out=crates/model/tests/fixtures
first=${1:-13}
last=${2:-$(sed -n 's/^pub const PROJECT_VERSION: u32 = \([0-9]*\);.*/\1/p' "$src")}
n=$first
while [ "$n" -le "$last" ]; do
    commit=$(git log --format=%h -S"PROJECT_VERSION: u32 = $n;" -- "$src" | tail -1)
    if [ -z "$commit" ]; then
        echo "version $n: no commit introduced it" >&2
        exit 1
    fi
    git show "$commit:examples/projects/demo.atomik" > "$out/demo-v$n.atomik"
    if ! grep -q "^  \"version\": $n,\$" "$out/demo-v$n.atomik"; then
        echo "version $n: the demo at $commit is not a version $n file" >&2
        exit 1
    fi
    echo "demo-v$n.atomik from $commit"
    n=$((n + 1))
done
